package com.aistock.notification.marketrefs;
import com.aistock.common.*;import com.aistock.common.marketrefs.*;import com.aistock.common.marketrefs.MarketReferenceRecords.*;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class MarketReferenceOwnerHttpTest {
 final String version="11111111-1111-1111-1111-111111111111",path=MarketReferenceInput.INTERNAL_BASE+"/"+version;ReferenceScanner scanner;MockMvc mvc;
 @BeforeEach void init(){scanner=mock(ReferenceScanner.class);when(scanner.scan(version)).thenReturn(new OwnerResult("notification",version,Instant.parse("2026-10-28T00:00:00Z"),"COMPLETE",null,List.of(new Group("records","记录","COMPLETE","0",null))));mvc=MockMvcBuilders.standaloneSetup(new MarketReferenceOwnerController(scanner)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new ReferenceTokenFilter("test",new ObjectMapper())).build();}
 @Test void requiresInternalIdentityAndDoesNotTrustRoleHeader()throws Exception{mvc.perform(get(path).header("X-Role","ADMIN")).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","no-store"));verifyNoInteractions(scanner);}
 @Test void returnsOnlyCorrectOwnerAggregate()throws Exception{mvc.perform(get(path).header("X-Service-Token","test")).andExpect(status().isOk()).andExpect(jsonPath("$.data.owner").value("notification")).andExpect(jsonPath("$.data.groups[0].rows").value("0"));verify(scanner).scan(version);}
 @Test void rejectsQueryBodyBadVersionAndWriteBeforeScanner()throws Exception{mvc.perform(get(path).header("X-Service-Token","test").param("x","1")).andExpect(status().isBadRequest());mvc.perform(get(path).header("X-Service-Token","test").content("{}")).andExpect(status().isBadRequest());mvc.perform(post(path).header("X-Service-Token","test")).andExpect(status().isNotFound());mvc.perform(get(MarketReferenceInput.INTERNAL_BASE+"/not-a-version").header("X-Service-Token","test")).andExpect(status().isBadRequest());verifyNoInteractions(scanner);}
}
